# Arrays


def _array_exclusive(a):
    if a.rc == 1:
        return a
    data = a.data
    for x in data:
        lean_inc(x)
    lean_dec(a)
    return LArray(list(data))


def lean_array_mk(xs):
    items = _list_to_py(xs)
    for x in items:
        lean_inc(x)
    lean_dec(xs)
    return LArray(items)


def lean_array_to_list(a):
    for x in a.data:
        lean_inc(x)
    return _py_to_list(a.data)


def lean_mk_empty_array_with_capacity(cap):
    return LArray([])


def lean_mk_array(n, v):
    if n == 0:
        lean_dec(v)
        return LArray([])
    lean_inc_n(v, n - 1)
    return LArray([v] * n)


def lean_array_get_size(a):
    return len(a.data)


def lean_array_size(a):
    return len(a.data)


def lean_array_fget(a, i):
    x = a.data[i]
    lean_inc(x)
    return x


def lean_array_fget_borrowed(a, i):
    return a.data[i]


def lean_array_uget(a, i):
    x = a.data[i]
    lean_inc(x)
    return x


def lean_array_uget_borrowed(a, i):
    return a.data[i]


def lean_array_get(default, a, i):
    if i < len(a.data):
        lean_dec(default)
        x = a.data[i]
        lean_inc(x)
        return x
    _panic_oob()
    return default


def lean_array_get_borrowed(default, a, i):
    if i < len(a.data):
        return a.data[i]
    _panic_oob()
    return default


def _panic_oob():
    _eprint("Error: index out of bounds")


def lean_array_push(a, v):
    a = _array_exclusive(a)
    a.data.append(v)
    return a


def lean_array_fset(a, i, v):
    a = _array_exclusive(a)
    old = a.data[i]
    a.data[i] = v
    lean_dec(old)
    return a


def lean_array_uset(a, i, v):
    return lean_array_fset(a, i, v)


def lean_array_set(a, i, v):
    if i >= len(a.data):
        lean_dec(v)
        _panic_oob()
        return a
    return lean_array_fset(a, i, v)


def lean_array_fswap(a, i, j):
    a = _array_exclusive(a)
    d = a.data
    d[i], d[j] = d[j], d[i]
    return a


def lean_array_swap(a, i, j):
    n = len(a.data)
    if i >= n or j >= n:
        return a
    return lean_array_fswap(a, i, j)


def lean_array_pop(a):
    a = _array_exclusive(a)
    if a.data:
        lean_dec(a.data.pop())
    return a


def lean_array_uswap(a, i, j):
    return lean_array_fswap(a, i, j)


def lean_array_propagate_mark(a):
    return a


def lean_copy_array(a):
    for x in a.data:
        lean_inc(x)
    return LArray(list(a.data))


def lean_array_extract(a, start, stop):
    d = a.data
    stop = min(stop, len(d))
    if start >= stop:
        return LArray([])
    items = d[start:stop]
    for x in items:
        lean_inc(x)
    return LArray(items)


