def lean_byte_array_copy_slice(src, src_off, dest, dest_off, length, exact):
    ssz = len(src.data)
    dsz = len(dest.data)
    src_off = min(src_off, ssz)
    length = min(length, ssz - src_off)
    dest_off = min(dest_off, dsz)
    chunk = src.data[src_off : src_off + length]
    r = _sarray_exclusive(dest, LByteArray)
    if dest_off + length > dsz:
        r.data.extend(bytes(dest_off + length - dsz))
    r.data[dest_off : dest_off + length] = chunk
    return r


def lean_byte_array_hash(a):
    return _murmur64a(bytes(a.data), 11)


