# Thunks and tasks (run synchronously)


def lean_mk_thunk(c):
    return Thunk(c)


def lean_thunk_pure(v):
    return Thunk(None, v, True)


def _thunk_force(t):
    if not t.done:
        t.value = lean_mark_persistent(lean_apply(t.fn, [0]))
        t.done = True
        t.fn = None
    return t.value


def lean_thunk_get_own(t):
    v = _thunk_force(t)
    lean_inc(v)
    return v


def lean_thunk_get(t):
    return _thunk_force(t)


def lean_task_pure(v):
    return Task(lean_mark_persistent(v))


def lean_task_spawn(c, prio=0):
    return Task(lean_mark_persistent(lean_apply(c, [0])))


def lean_task_get_own(t):
    v = t.value
    lean_inc(v)
    return v


def lean_task_get(t):
    return t.value


def lean_task_map(f, t, prio=0, sync=0):
    return Task(lean_mark_persistent(lean_apply(f, [t.value])))


def lean_task_bind(t, f, prio=0, sync=0):
    return lean_apply(f, [t.value])


def lean_io_wait(t, _w=0):
    return t.value


